<script>const modal=document.getElementById('modal');function openModal(s){modal.classList.add('show');if(s){const x=document.getElementById('service');[...x.options].forEach(o=>{if(o.text.toLowerCase().includes(s.toLowerCase().split(' ')[0]))x.value=o.text})}}function closeModal(){modal.classList.remove('show')}modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.project').forEach(p=>p.style.display=b.dataset.filter==='all'||b.dataset.filter===p.dataset.category?'':'none')});function faq(b){b.parentElement.classList.toggle('open')}function calc(){const a=Math.max(10,Number(document.getElementById('area').value)||100),t=document.getElementById('type').value,l=Number(document.getElementById('level').value),r={desain:[80000,140000],bangun:[6500000,9000000],renovasi:[3500000,6000000],interior:[1800000,3200000]}[t],f=n=>n>=1e9?'Rp '+(n/1e9).toFixed(2).replace('.',',')+' M':'Rp '+Math.round(n/1e6)+' Jt';document.getElementById('budget').textContent=f(a*r[0]*l)+' – '+f(a*r[1]*l)}calc();</script></body></html>